import java.util.Scanner;
public class JNestedIfMinOfThree
{
	public static void main (String[] args)
	{
		//Khutwa 1: Iqra al-aedad al-thalatha
		Scanner scan = new Scanner (System.in);
		System.out.println("Adkhil thalathat aedad sahihah: ");
		int num1 = scan.nextInt();
		int num2 = scan.nextInt();
		int num3 = scan.nextInt();
		scan.close();
		//Khutwa 2: Tayin al-adad al-asghar
		int min;
		if (num1 < num2) {
			if (num1 < num3) {
				min = num1;
			} else {
				min = num3;
			}
		} else {
			if (num2 < num3) {
				min = num2;
			} else {
				min = num3;
			}
		}
		//Khutwa 3: Taba al-adad al-asghar
		System.out.println ("Al-qima al-asghar: " + min);
	}
}
